config.code:
td = bindings.get('table_data') or {}
rows = td.get('rows') or []
if not rows:
    bindings['sample_md'] = ''
else:
    cols = list(rows[0].keys())
    lines = ['\\n## 样例数据（前 %d 行）\\n' % len(rows)]
    lines.append('| ' + ' | '.join(cols) + ' |')
    lines.append('|' + '|'.join('---' for _ in cols) + '|')
    for r in rows:
        cells = []
        for c in cols:
            v = r.get(c)
            cells.append('' if v is None else str(v).replace('|', '\\\\|')[:80])
        lines.append('| ' + ' | '.join(cells) + ' |')
    bindings['sample_md'] = '\\n'.join(lines)
